def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); groups={}
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            col=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                a,b=stack.pop(); pts.append((a,b))
                for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                    if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==col:
                        seen.add((x,y)); stack.append((x,y))
            ar=min(x for x,y in pts); ac=min(y for x,y in pts)
            key=tuple(sorted((x-ar,y-ac) for x,y in pts))
            groups.setdefault(key,[]).append(pts)
    out=[[0]*w for _ in range(h)]
    for objects in groups.values():
        if len(objects)>1:
            for pts in objects:
                for r,c in pts: out[r][c]=grid[r][c]
    return out

